import { MakeLogicType, afterMount, connect, kea, listeners, path, selectors, useValues } from 'kea'
import { loaders } from 'kea-loaders'

import { FeatureFlagKey } from 'lib/constants'
import { permanentlyMount } from 'lib/utils/kea-logic-builders'

import { toolbarConfigLogic } from '~/toolbar/toolbarConfigLogic'
import { toolbarPosthogJS, useToolbarFeatureFlag } from '~/toolbar/toolbarPosthogJS'
import { safeFetch } from '~/toolbar/utils'
import { AvailableFeature } from '~/types'

export type ToolbarEntitlements = Record<string, boolean>

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface toolbarEntitlementsLogicValues {
    isAuthenticated: boolean // toolbarConfigLogic
    uiHost: string // toolbarConfigLogic
    entitlements: ToolbarEntitlements | null
    entitlementsLoading: boolean
    isEntitled: (feature: AvailableFeature) => boolean
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface toolbarEntitlementsLogicActions {
    setOAuthTokens: (
        accessToken: string,
        refreshToken: string | null,
        clientId: string
    ) => {
        accessToken: string
        clientId: string
        refreshToken: string | null
    } // toolbarConfigLogic
    loadEntitlements: () => any
    loadEntitlementsFailure: (
        error: string,
        errorObject?: any
    ) => {
        error: string
        errorObject?: any
    }
    loadEntitlementsSuccess: (
        entitlements: ToolbarEntitlements | null,
        payload?: any
    ) => {
        entitlements: ToolbarEntitlements | null
        payload?: any
    }
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface toolbarEntitlementsLogicMeta {
    __keaTypeGenInternalSelectorTypes: {
        isEntitled: (entitlements: ToolbarEntitlements | null) => (feature: AvailableFeature) => boolean
    }
}

export type toolbarEntitlementsLogicType = MakeLogicType<
    toolbarEntitlementsLogicValues,
    toolbarEntitlementsLogicActions,
    Record<string, any>,
    toolbarEntitlementsLogicMeta
>

export const toolbarEntitlementsLogic = kea<toolbarEntitlementsLogicType>([
    path(['toolbar', 'toolbarEntitlementsLogic']),
    connect(() => ({
        values: [toolbarConfigLogic, ['uiHost', 'isAuthenticated']],
        actions: [toolbarConfigLogic, ['setOAuthTokens']],
    })),
    loaders(({ values }) => ({
        entitlements: [
            null as ToolbarEntitlements | null,
            {
                loadEntitlements: async () => {
                    try {
                        const response = await safeFetch(`${values.uiHost}/api/user/toolbar_entitlements`, {
                            credentials: 'include',
                        })
                        if (!response.ok) {
                            return null
                        }
                        const data = await response.json()
                        return (data.entitlements as ToolbarEntitlements) ?? null
                    } catch {
                        return null
                    }
                },
            },
        ],
    })),
    selectors({
        isEntitled: [
            (s) => [s.entitlements],
            (entitlements: ToolbarEntitlements | null) =>
                (feature: AvailableFeature): boolean =>
                    entitlements?.[feature] !== false,
        ],
    }),
    listeners(({ actions }) => ({
        setOAuthTokens: () => {
            actions.loadEntitlements()
        },
    })),
    afterMount(({ actions, values }) => {
        if (values.isAuthenticated) {
            actions.loadEntitlements()
        }
    }),
    permanentlyMount(),
])

export function useToolbarEntitlement(feature: AvailableFeature): boolean {
    const { isEntitled } = useValues(toolbarEntitlementsLogic)
    return isEntitled(feature)
}

export function useToolbarFeatureGate(feature: AvailableFeature, rolloutFlag: FeatureFlagKey): boolean {
    const rolloutEnabled = useToolbarFeatureFlag(rolloutFlag)
    const entitled = useToolbarEntitlement(feature)
    return rolloutEnabled && !entitled
}

export function isToolbarFeatureGated(feature: AvailableFeature, rolloutFlag: FeatureFlagKey): boolean {
    const rolloutEnabled = !!toolbarPosthogJS.getFeatureFlag(rolloutFlag)
    const entitled = toolbarEntitlementsLogic.findMounted()?.values.isEntitled(feature) ?? true
    return rolloutEnabled && !entitled
}
